#include <unity.h>
#include <imu_frame.h>
#include <cfloat>
#include <cmath>
#include <cstring>

void setUp(void) {}

void tearDown(void) {}

// Goldens generated by freecad-workspace dof_frame.format_frame (verified 2026-10-20).
static const char kG1[] =
    "IMU,12345,1234567890,0.500000,-9.806650,1.250000,10.500000,-5.500000,0.000000*52\n";
static const char kG0[] =
    "IMU,0,0,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000*51\n";
static const char kG2[] =
    "IMU,65535,4294967295,0.000000,0.000000,0.000000,0.000000,0.000000,0.000000*6C\n";
static const char kNegMicro[] =
    "IMU,0,0,-0.000001,0.000000,0.000000,0.000000,0.000000,0.000000*7D\n";

static const float kZero[3] = {0.0f, 0.0f, 0.0f};

// Test 1: G1 golden, exact string and length
void test_golden_G1(void) {
  const float accel[3] = {0.5f, -9.80665f, 1.25f};
  const float gyro[3] = {10.5f, -5.5f, 0.0f};
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 12345, 1234567890u, accel, gyro);
  TEST_ASSERT_EQUAL_UINT(81, n);
  TEST_ASSERT_EQUAL_STRING(kG1, buf);
  TEST_ASSERT_EQUAL_UINT(strlen(kG1), n);
}

// Test 2: G0 golden, all zero
void test_golden_G0(void) {
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(65, n);
  TEST_ASSERT_EQUAL_STRING(kG0, buf);
}

// Test 3: G2 golden, seq and t_us maxima
void test_golden_G2(void) {
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 65535, 4294967295u, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(78, n);
  TEST_ASSERT_EQUAL_STRING(kG2, buf);
}

// Test 4: checksum golden values
void test_checksum_IMU_comma(void) {
  TEST_ASSERT_EQUAL_HEX8(0x7D, imu_frame::checksum("IMU,", 4));
}

void test_checksum_single_byte(void) {
  TEST_ASSERT_EQUAL_HEX8(0x41, imu_frame::checksum("A", 1));
}

void test_checksum_two_bytes(void) {
  TEST_ASSERT_EQUAL_HEX8(0x03, imu_frame::checksum("AB", 2));
}

// Test 5: n == 0 and nullptr give 0
void test_checksum_empty_and_null(void) {
  TEST_ASSERT_EQUAL_HEX8(0x00, imu_frame::checksum("IMU,", 0));
  TEST_ASSERT_EQUAL_HEX8(0x00, imu_frame::checksum(nullptr, 4));
}

// Test 6: checksum of the G0 body (up to '*') is 0x51
void test_checksum_G0_body(void) {
  const size_t body_len = static_cast<size_t>(strchr(kG0, '*') - kG0);
  TEST_ASSERT_EQUAL_UINT(61, body_len);
  TEST_ASSERT_EQUAL_HEX8(0x51, imu_frame::checksum(kG0, body_len));
}

// Test 7: -0.0f is printed as 0.000000
void test_negative_zero_is_normalized(void) {
  const float accel[3] = {-0.0f, 0.0f, 0.0f};
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, accel, kZero);
  TEST_ASSERT_EQUAL_UINT(65, n);
  TEST_ASSERT_EQUAL_STRING(kG0, buf);
}

// Test 8: tiny negatives whose %.6f text is all zeros print without sign
void test_tiny_negatives_normalize_to_zero(void) {
  const float tiny[3] = {-1e-9f, -4e-7f, 1e-9f};
  char buf[256];
  for (int i = 0; i < 3; i++) {
    float accel[3] = {0.0f, 0.0f, 0.0f};
    accel[0] = tiny[i];
    size_t n = imu_frame::format(buf, sizeof buf, 0, 0, accel, kZero);
    TEST_ASSERT_EQUAL_UINT(65, n);
    TEST_ASSERT_EQUAL_STRING(kG0, buf);
  }
}

// Test 9: -6e-7 rounds to -0.000001 and keeps its sign
void test_minus_six_e7_keeps_sign(void) {
  const float accel[3] = {-6e-7f, 0.0f, 0.0f};
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, accel, kZero);
  TEST_ASSERT_EQUAL_UINT(strlen(kNegMicro), n);
  TEST_ASSERT_EQUAL_STRING(kNegMicro, buf);
}

// Test 10: NaN and infinities become 0.0
void test_nonfinite_becomes_zero(void) {
  const float accel[3] = {NAN, INFINITY, -INFINITY};
  const float gyro[3] = {-INFINITY, NAN, INFINITY};
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, accel, gyro);
  TEST_ASSERT_EQUAL_UINT(65, n);
  TEST_ASSERT_EQUAL_STRING(kG0, buf);
}

// Test 11: cap 66 fits G0 (65 chars + NUL)
void test_cap_just_fits(void) {
  char buf[66];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(65, n);
  TEST_ASSERT_EQUAL_STRING(kG0, buf);
}

// Test 12: cap 65 has no room for the NUL
void test_cap_no_room_for_nul(void) {
  char buf[65];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[0]);
}

// Test 13: cap 64 is too small
void test_cap_64_too_small(void) {
  char buf[64];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[0]);
}

// Test 14: cap 1 writes only the NUL
void test_cap_one(void) {
  char buf[1];
  buf[0] = 'X';
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[0]);
}

// Test 15: cap 0 writes nothing (canary byte stays)
void test_cap_zero_untouched(void) {
  char buf[4] = {0x55, 0x55, 0x55, 0x55};
  size_t n = imu_frame::format(buf, 0, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_HEX8(0x55, static_cast<unsigned char>(buf[0]));
  TEST_ASSERT_EQUAL_HEX8(0x55, static_cast<unsigned char>(buf[3]));
}

// Test 16: cap 40 with a 81-char frame never writes at or past index 39
void test_canary_never_written_past_cap(void) {
  const float accel[3] = {0.5f, -9.80665f, 1.25f};
  const float gyro[3] = {10.5f, -5.5f, 0.0f};
  unsigned char buf[200];
  memset(buf, 0x55, sizeof buf);
  size_t n = imu_frame::format(reinterpret_cast<char*>(buf), 40, 12345, 1234567890u,
                               accel, gyro);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', static_cast<char>(buf[0]));
  for (size_t i = 40; i < sizeof buf; i++) {
    TEST_ASSERT_EQUAL_HEX8(0x55, buf[i]);
  }
}

// Test 17: FLT_MAX in every slot does not fit in 128 bytes, no overflow
void test_flt_max_does_not_fit(void) {
  const float big[3] = {FLT_MAX, FLT_MAX, FLT_MAX};
  unsigned char buf[200];
  memset(buf, 0x55, sizeof buf);
  size_t n = imu_frame::format(reinterpret_cast<char*>(buf), 128, 0, 0, big, big);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', static_cast<char>(buf[0]));
  for (size_t i = 128; i < sizeof buf; i++) {
    TEST_ASSERT_EQUAL_HEX8(0x55, buf[i]);
  }
}

// Test 18: a huge finite value is printed in full when it fits
void test_huge_finite_printed_in_full(void) {
  const float accel[3] = {3e38f, 0.0f, 0.0f};
  char buf[256];
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, accel, kZero);
  TEST_ASSERT_TRUE(n > 65);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[n]);
  TEST_ASSERT_EQUAL_CHAR('\n', buf[n - 1]);
  TEST_ASSERT_EQUAL_INT(0, strncmp(buf, "IMU,0,0,3", 9));
  TEST_ASSERT_NOT_NULL(strstr(buf, ".000000,0.000000,0.000000,0.000000,0.000000,0.000000*"));
}

// Test 19: nullptr out gives 0
void test_null_out_returns_zero(void) {
  size_t n = imu_frame::format(nullptr, 100, 0, 0, kZero, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
}

// Test 20: nullptr arrays give 0 and out[0] is cleared
void test_null_arrays_return_zero(void) {
  char buf[100];
  buf[0] = 'X';
  size_t n = imu_frame::format(buf, sizeof buf, 0, 0, nullptr, kZero);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[0]);

  buf[0] = 'X';
  n = imu_frame::format(buf, sizeof buf, 0, 0, kZero, nullptr);
  TEST_ASSERT_EQUAL_UINT(0, n);
  TEST_ASSERT_EQUAL_CHAR('\0', buf[0]);
}

int main(int argc, char **argv) {
  UNITY_BEGIN();
  RUN_TEST(test_golden_G1);
  RUN_TEST(test_golden_G0);
  RUN_TEST(test_golden_G2);
  RUN_TEST(test_checksum_IMU_comma);
  RUN_TEST(test_checksum_single_byte);
  RUN_TEST(test_checksum_two_bytes);
  RUN_TEST(test_checksum_empty_and_null);
  RUN_TEST(test_checksum_G0_body);
  RUN_TEST(test_negative_zero_is_normalized);
  RUN_TEST(test_tiny_negatives_normalize_to_zero);
  RUN_TEST(test_minus_six_e7_keeps_sign);
  RUN_TEST(test_nonfinite_becomes_zero);
  RUN_TEST(test_cap_just_fits);
  RUN_TEST(test_cap_no_room_for_nul);
  RUN_TEST(test_cap_64_too_small);
  RUN_TEST(test_cap_one);
  RUN_TEST(test_cap_zero_untouched);
  RUN_TEST(test_canary_never_written_past_cap);
  RUN_TEST(test_flt_max_does_not_fit);
  RUN_TEST(test_huge_finite_printed_in_full);
  RUN_TEST(test_null_out_returns_zero);
  RUN_TEST(test_null_arrays_return_zero);
  return UNITY_END();
}
